// HasPreset applies the HasEdge predicate on the "preset" edge.
func HasPreset() predicate.RetryFilterRule {
	return predicate.RetryFilterRule(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PresetTable, PresetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPresetWith applies the HasEdge predicate on the "preset" edge with a given conditions (other predicates).
func HasPresetWith(preds ...predicate.RetryFilterPreset) predicate.RetryFilterRule {
	return predicate.RetryFilterRule(func(s *sql.Selector) {
		step := newPresetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RetryFilterRule) predicate.RetryFilterRule {
	return predicate.RetryFilterRule(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RetryFilterRule) predicate.RetryFilterRule {
	return predicate.RetryFilterRule(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RetryFilterRule) predicate.RetryFilterRule {
	return predicate.RetryFilterRule(sql.NotPredicates(p))
}
